            ['start_time' => 3171.27, 'end_time' => 3174.32, 'target_text' => 'You know, it\'s not easy to put your name next to a charity.', 'source_text' => 'Anda tahu, bukanlah mudah untuk meletakkan nama anda bersama sebuah badan kebajikan.', 'order' => 1073],
